function write_str(
  parts: Array<string>,
  value: string
): void {
  parts.push(escapeXmlText(value));
}

function write_bytes(
  parts: Array<string>,
  value: Uint8Array
): void {
  parts.push(escapeXmlText(OurCommon.base64Encode(value)));
}

